using System;
using System.IO;
using System.Linq;
namespace Touchfish {
public partial class PanelWindow {
 public void PreviewPaladinShamanScope(string folder){previewRun=true;Directory.CreateDirectory(folder);int before=checks;Check(catalog.Deckable(catalog.Pool("classic-2014")).Where(c=>c.CardClass=="PALADIN"||c.CardClass=="SHAMAN").All(matchRules.Supports),"Both classes fully enabled in builder");VerifyPaladinShamanTcp(folder);File.WriteAllText(Path.Combine(folder,"paladin-shaman-verification.txt"),"PASS: "+(checks-before)+" focused assertions; Sword durability, Guardian heal, Far Sight instance cost, Ancestral restoration, Hex, overload triggers and actual loopback TCP.");}
 void VerifyPaladinShamanTcp(string folder){if(!VerificationRun.Network)return;LeaveLan();ApplyTheme(true,true);ApplyMode(false);SetFullEffects(false);var guest=new PanelWindow(true){ShowInTaskbar=false,Opacity=0};guest.Show();guest.ApplyTheme(true,true);guest.ApplyMode(false);try{
  lanPort.Text=FreeLanPort().ToString();lanDeck.SelectedIndex=0;lanClass.SelectedItem=Classes.First(c=>c.Key=="PALADIN");BeginLan(true);guest.lanDeck.SelectedIndex=0;guest.lanClass.SelectedItem=Classes.First(c=>c.Key=="SHAMAN");guest.lanAddress.Text="127.0.0.1:"+lanPort.Text;guest.BeginLan(false);PumpLan(()=>lanReady&&guest.lanReady,"Paladin Shaman peers connect");DoMatch("mulligan",selectedIds:new int[0]);PumpLan(()=>guest.match.Players[0].MulliganDone,"Host mulligan reaches guest");guest.DoMatch("mulligan",selectedIds:new int[0]);PumpLan(()=>match.MulliganComplete&&!guest.lanWaiting,"Both mulligans complete");var g=lanAuthority.Game;foreach(var p in g.Players){p.Hand.Clear();p.Board.Clear();p.Mana=p.MaxMana=10;}g.Players[0].Health=20;int sword=Inject(g,"EX1_366"),guardian=Inject(g,"CS2_088");PublishLan();BeginCard(sword);PumpLan(()=>guest.match.Players[0].WeaponDurability==5,"Sword equipped on both peers");BeginCard(guardian);ClickEmptySlot(0,0);PumpLan(()=>guest.match.Players[0].Health==26&&guest.match.Players[0].WeaponDurability==4,"Guardian heal and Sword consumption synchronize");Check(guest.match.Players[0].Board.Single().Health==7,"Sword buffs played Guardian");DoMatch("end");PumpLan(()=>guest.match.Active==1,"Guest Shaman turn starts");
  g.Players[1].Hand.Clear();g.Players[1].Deck.Clear();g.Players[1].Deck.Add("VAN_CS2_182");g.Players[1].Mana=10;var unbound=g.Summon(1,"VAN_EX1_258");int sight=Inject(g,"CS2_053",1),ancestral=Inject(g,"CS2_038",1);PublishLan();PumpLan(()=>guest.match.Players[1].Hand.Any(h=>h.Id==sight),"Far Sight reaches private guest hand");guest.BeginCard(sight);PumpLan(()=>!guest.lanWaiting&&guest.match.Players[1].Hand.Any(h=>h.CostAdjustment==-3),"Far Sight instance discount reaches client");var discounted=guest.match.Players[1].Hand.Single(h=>h.CostAdjustment==-3);Check(guest.match.HandCost(1,discounted)==1&&LanProtocol.View(g,0,"class",1).Players[1].Hand.Length==0,"Guest sees correct cost while host public view hides hand");guest.BeginCard(discounted.Id);guest.ClickEmptySlot(1,1);PumpLan(()=>!guest.lanWaiting&&g.Players[1].Board.Count==2,"Discounted Yeti plays on authority");var body=g.Players[1].Board.Single(u=>u.CardId=="VAN_CS2_182");guest.BeginCard(ancestral);guest.ClickMatchTarget(new MatchTarget(1,body.Id));PumpLan(()=>!guest.lanWaiting&&guest.match.Players[1].Board.Any(u=>u.AncestralSpirits==1),"Ancestral enchantment synchronized");guest.InspectMatchCard(guest.match.Card(body.CardId),guest.match.Players[1].Board.Single(u=>u.Id==body.Id));Check(guest.ForestDetail().Contains("先祖之魂"),"Ancestral detail visible on demand");guest.Opacity=1;guest.Render(Path.Combine(folder,"131-ancestral-details-codex.png"));guest.Opacity=0;guest.inspectMatch=false;guest.DoMatch("end");PumpLan(()=>!guest.lanWaiting&&g.Active==0,"Turn returns to host");
  g.Players[0].Mana=10;int fire=Inject(g,"CS2_029");PublishLan();BeginCard(fire);ClickMatchTarget(new MatchTarget(1,body.Id));PumpLan(()=>guest.match.Players[1].Board.Any(u=>u.CardId=="VAN_CS2_182"&&u.Id!=body.Id),"Ancestral restoration reaches guest");Check(g.Players[1].Board.Count==2&&g.Players[1].Board[1].AncestralSpirits==0&&g.Players[1].Board[1].Health==5,"Restored base minion at original position has no recursive grant");DoMatch("end");PumpLan(()=>guest.match.Active==1,"Guest second turn starts");g.Players[1].Hand.Clear();g.Players[1].Mana=10;int hex=Inject(g,"EX1_246",1),bolt=Inject(g,"EX1_238",1);PublishLan();PumpLan(()=>guest.match.Players[1].Hand.Any(h=>h.Id==hex),"Hex reaches guest hand");var target=g.Players[0].Board.Single();int durability=g.Players[0].WeaponDurability;guest.BeginCard(hex);guest.ClickMatchTarget(new MatchTarget(0,target.Id));PumpLan(()=>!guest.lanWaiting&&g.Players[0].Board.Single().CardId=="GAME_FROG","Guest Hex transforms on host");Check(guest.match.Players[0].Board.Single().Health==1&&guest.match.Players[0].Board.Single().Taunt&&g.Players[0].WeaponDurability==durability,"Hex Frog is unbuffed and does not consume Sword");guest.BeginCard(bolt);guest.ClickMatchTarget(new MatchTarget(0));PumpLan(()=>!guest.lanWaiting&&g.Players[1].Overload==1,"Overload spell resolves on host");Check(g.AttackValue(unbound)==3&&guest.match.Players[1].Board.Single(u=>u.Id==unbound.Id).MaxHealth==5,"Unbound overload buff synchronizes");Render(Path.Combine(folder,"132-paladin-shaman-codex.png"));
 }finally{guest.LeaveLan();guest.Close();LeaveLan();}}
}
}
